"""Dated licensed provider facts plus official statistics, no affiliate or recommendations."""
from pathlib import Path
from html import escape as e
import json,datetime,shutil
from comparisons_data import load_series
ROOT=Path(__file__).resolve().parent;DATA=ROOT.parent/'content/comparisons'
LICENSE='https://creativecommons.org/licenses/by/4.0/deed.de'
POLICY='https://www.ecb.europa.eu/stats/ecb_statistics/governance_and_quality_framework/html/usage_policy.en.html'
def n(v):return ('%.2f'%float(v)).replace('.',',')
def attribution():return '<p class="cmp-source">Daten: <a href="https://vermoegen-sparen.de/daten">Vermögen sparen</a> · <a href="'+LICENSE+'">CC BY 4.0</a> · Feed-Stand 18.10.2026, Abruf 19.10.2026. FA: Auswahl, Neuanordnung und eigene Modellberechnungen; keine übernommenen Testnoten. Ausgewählte Tagesgeldbedingungen am 19.10.2026 gegen Anbieter gegengeprüft. Keine Partnerschaft mit den genannten Anbietern, keine Affiliate-Links.</p>'
def stale_banner(date,today):
    age=(today-datetime.date.fromisoformat(date)).days
    return '<p class="cmp-alert">Historischer Datenstand: Konditionen sind älter als 45 Tage. Vor einem Abschluss unbedingt direkt beim Anbieter prüfen. Keine aktuellen Angebote.</p>' if age>45 else ''
def spark(rows):
    vals=[float(r['OBS_VALUE']) for r in rows];lo=min(vals);hi=max(vals);span=hi-lo or 1
    points=' '.join('%.1f,%.1f'%(10+i*300/(len(vals)-1),85-(v-lo)*65/span) for i,v in enumerate(vals))
    return '<svg viewBox="0 0 320 100" role="img" aria-label="Verlauf der letzten '+str(len(vals))+' Monatswerte; Werte in Tabelle darunter"><path d="M10 90H310" stroke="currentColor" opacity=".2"/><polyline points="'+points+'" fill="none" stroke="currentColor" stroke-width="3"/></svg>'
def build_comparisons(page,urls,out,base):
    snapshot=json.loads((DATA/'conditions-2026-10-19.json').read_text());offers=json.loads((DATA/'savings-models.json').read_text())
    for name in ['comparisons.css','comparisons.js','comparison-math.js']:shutil.copyfile(ROOT/name,Path(out)/name)
    shutil.copytree(DATA,Path(out)/'comparison-data',dirs_exist_ok=True)
    assets='<link rel="stylesheet" href="/calculators.css"><link rel="stylesheet" href="/comparisons.css">'
    scripts='<script src="/comparison-math.js" defer></script><script src="/comparisons.js" defer></script>'
    nav='<nav class="cmp-nav" aria-label="Vergleichsthemen"><a href="/vergleiche/">Übersicht</a><a href="/vergleiche/tagesgeld/">Tagesgeld</a><a href="/vergleiche/depot/">Depot &amp; Broker</a><a href="/vergleiche/zinsmonitor/">Amtlicher Zinsmonitor</a></nav>'
    warning='<aside class="calc-note"><h2>Vergleichen, nicht empfehlen.</h2><p>Eine begrenzte, kuratierte Auswahl, kein vollständiger Marktüberblick und keine Bestenliste. Daten können sich jederzeit ändern. Nur Kosten und Zinsen zu vergleichen reicht nicht: Verfügbarkeit, Service, Risiken und Vertragsbedingungen gehören dazu. Keine Anlage-, Kredit- oder Steuerberatung. <a href="/risikohinweis/">Risikohinweis</a>.</p></aside>'
    def publish(slug,title,intro,body):
        path='/vergleiche/'+(slug+'/' if slug else '')
        credit=('<p class="cmp-source">Quelle: EZB-Statistiken. Unveränderte Beobachtungen und Original-Metadaten im CSV, eigene Auswahl, Kurzbezeichnungen und SVG-Darstellung durch FA. <a href="'+POLICY+'">Nutzungsbedingungen</a>. Keine Verbindung zur EZB.</p>' if slug=='zinsmonitor' else attribution())
        content=assets+'<main class="calc-wrap cmp-wrap">'+nav+'<p class="calc-kicker">FA VERGLEICHE / OHNE AFFILIATE</p><h1>'+e(title)+'</h1><p class="calc-lead">'+e(intro)+'</p>'+stale_banner('2026-10-19',datetime.date.today())+body+credit+warning+'</main>'
        urls.append(page(path,title+' | finanz adjust',intro,content,act='/rechner/',crumbs=[('/vergleiche/','Vergleiche')]+([(path,title)] if slug else [])))
    publish('','Konditionen verstehen. Fair vergleichen.','Keine bezahlte Platzierung. Anbieter-Konditionen aus offenen Daten, eigene Rechenmodelle und ein amtlicher Zinsmonitor.','<div class="calc-cards">'+''.join('<a class="calc-card" href="/vergleiche/'+slug+'/"><span class="calc-icon" aria-hidden="true">'+icon+'</span><h2>'+title+'</h2><p>'+desc+'</p><b>Vergleich ansehen →</b></a>' for slug,icon,title,desc in [('tagesgeld','€','Tagesgeld im Szenario','Aktionszins und Anschlusszins getrennt rechnen. Drei ausgewählte Konten, alle Grenzen sichtbar.'),('depot','%','Depot & Broker','Zehn Anbieter mit Gebührenbedingungen und Quellen. Dazu ein neutraler A/B-Kostenrechner mit eigenen Eingaben.'),('zinsmonitor','↗','Amtlicher Zinsmonitor','Deutsche Einlagen- und Kreditzinsen aus EZB-Statistiken, mit Monatsstand und Verlauf. Keine Einzelangebote.')])+'</div><section class="calc-info"><h2>Die Quelle ist Teil des Vergleichs</h2><p>Der offene Datensatz liefert Zahlen und Bedingungen unter CC BY 4.0. Pauschale Kennzahlen können irreführen: Mindestgebühren, Handelsplätze oder befristete Zinsen verändern den Vergleich. Deshalb zeigen wir die Bedingungen und keine vereinfachte Gesamtnote.</p><p><a href="/rechner/">Alle acht Finanzrechner →</a></p></section>')
    cards=''
    for o in offers:
        shown=o.get('promo',o['base'])
        cards+='<article class="cmp-offer"><div class="cmp-offer-head"><span class="cmp-monogram" aria-hidden="true">'+e(o['name'][:2].upper())+'</span><div><h2>'+e(o['name'])+'</h2><small>Prüfung: '+o['checked']+'</small></div></div><p class="cmp-rate">'+n(shown)+' % <small>p. a.'+(' · 6 Monate Aktion' if o['kind']=='promo' else ' · variabel')+'</small></p><p>'+e(o['conditions'])+'</p><a href="'+e(o['source'],quote=True)+'" rel="noopener noreferrer">Konditionen beim Anbieter prüfen ↗</a><div class="cmp-model" data-offer="'+o['id']+'"><b>Modell-Ertrag: JavaScript nötig</b></div></article>'
    savings='<p class="cmp-alert">Daten-Snapshot, keine Live-Angebote. Zinsen variabel oder befristet. Bei der Aktion wird ein Neukundenstart und geeignetes neues Guthaben unterstellt. Keine Eröffnung über FA möglich.</p><form id="cmp-savings" class="cmp-controls"><fieldset id="cmp-savings-fields" disabled><legend>Dein Brutto-Zinsszenario</legend><label>Anlagebetrag (€)<input name="amount" type="text" inputmode="decimal" value="10.000" required></label><label>Zeitraum (Monate, 1–24)<input name="months" type="text" inputmode="numeric" value="12" required></label><label class="cmp-check"><input name="eligible" type="checkbox" checked>Aktionsbedingungen bei 1822direkt erfüllt</label><button>Neu berechnen</button><button type="reset" class="calc-secondary">Zurücksetzen</button></fieldset><noscript><p>Berechnung braucht JavaScript. Keine Eingaben werden abgesendet.</p></noscript><p id="cmp-error" role="alert" hidden></p></form><div class="cmp-offers">'+cards+'</div><p id="cmp-savings-status" role="status" aria-live="polite"></p><section class="calc-info"><h2>Ein Zinssatz ist noch kein Jahresertrag</h2><p>Die Modellrechnung teilt Jahreszinsen durch zwölf und summiert Monatszinsen ohne Zinseszins. Einlagen bleiben konstant, es gibt keine Steuern, Gebühren oder taggenaue Abrechnung. Der angezeigte variable Basiszins bleibt im Szenario unverändert, das ist keine Vorhersage. Obergrenzen und GEFA-Guthabenband werden berücksichtigt. Beträge bis 1 Mio. € sind Rechenwerte, keine Aussage zur Einlagensicherung.</p><p>1822-Aktion: sechs Monate Sonderzins, danach Basiszins; oberhalb 250.000 € sofort Basiszins. GEFA: liegt das gesamte Guthaben außerhalb 10.000–500.000 €, ist im Modell die komplette Verzinsung null. willbe: nur der Teil bis 150.000 € wird verzinst. Unterschiedliche Sicherungssysteme, Länder und persönliche Voraussetzungen sind nicht bewertet.</p><h3>Quellen &amp; Änderungen</h3><p><a href="/comparison-data/conditions-2026-10-19.json">Offener Feed-Snapshot</a> · <a href="/comparison-data/savings-models.json">Kuratiertes Rechenmodell</a>. Änderungen gegenüber dem Feed: nur drei gegengeprüfte Konten; willbe-Maximum und GEFA-Band explizit behandelt; keine Festgeld-Mindesteinlagen als Tagesgeldgrenzen übernommen.</p></section><script type="application/json" id="cmp-offers">'+json.dumps(offers,ensure_ascii=False).replace('<','\\u003c')+'</script>'+scripts
    publish('tagesgeld','Tagesgeld: Aktion ist nicht Dauerzins','Drei ausgewählte Konten mit nachvollziehbarer Brutto-Modellrechnung. Alphabetisch, nicht nach Provision oder vermeintlicher Qualität sortiert.',savings)
    rows=''
    for b in sorted(snapshot['broker'],key=lambda x:x['name'].lower()):
        source=b.get('konditionenQuelle',{});age_note=stale_banner(source.get('geprueftAm',b['geprueftAm']),datetime.date.today());conditions=''.join('<li><b>'+e(c['position'])+':</b> '+e(c['text'])+'</li>' for c in b['konditionen'] if not any(x in c['position'].lower() for x in ['krypto','usa','ausland']))
        rows+='<article class="cmp-broker"><h2>'+e(b['name'])+'</h2>'+age_note+'<p class="cmp-date">Datensatz-Prüfdatum '+e(b['geprueftAm'])+' · Preisquelle laut Datensatz '+e(source.get('geprueftAm','nicht genannt'))+'</p><ul>'+conditions+'</ul><p><a href="'+e(source.get('url',b['url']),quote=True)+'" rel="noopener noreferrer">Genanntes Preisverzeichnis ↗</a> · <a href="'+e(b['url'],quote=True)+'">Datensatz-Eintrag ↗</a></p></article>'
    broker='<p class="cmp-alert">Daten Dritter, nicht von FA vollständig gegen jedes Preisverzeichnis geprüft. Datensatz- und Preisquellen-Prüfdatum unterscheiden sich. Kein automatisch berechnetes Anbieterranking. Angaben nur für die jeweils genannte Orderart, das Produkt und den Handelsplatz.</p><section class="calc-info"><h2>Dein eigener A/B-Kostenvergleich</h2><p>Trage zwei passende Gebührenmodelle aus einem Preisverzeichnis ein. Die Startwerte sind fiktiv, keinem Anbieter zugeordnet. Mindest-/Höchstgebühren, Staffelpreise und Aktionen sind hier NICHT modelliert. Bei solchen Tarifen hilft die Tabelle weiter, nicht dieser einfache Rechner.</p><form id="cmp-broker-form" class="cmp-controls"><fieldset id="cmp-broker-fields" disabled><legend>Jährliche Modellkosten</legend><label>Orders pro Jahr (0–10.000)<input name="orders" value="12" inputmode="numeric"></label><label>Ordervolumen (€)<input name="volume" value="1.000" inputmode="decimal"></label>'+''.join('<div class="cmp-ab"><h3>Fiktives Modell '+letter+'</h3><label>Fixkosten je Order (€)<input name="fixed'+letter+'" value="'+fixed+'" inputmode="decimal"></label><label>Provision je Order (%)<input name="percent'+letter+'" value="0" inputmode="decimal"></label><label>Depotkosten pro Monat (€)<input name="monthly'+letter+'" value="0" inputmode="decimal"></label></div>' for letter,fixed in [('A','1'),('B','5')])+'<button>Vergleichen</button><button type="reset" class="calc-secondary">Zurücksetzen</button></fieldset><noscript><p>JavaScript erforderlich, keine Übermittlung.</p></noscript><p id="cmp-broker-error" role="alert" hidden></p></form><div id="cmp-broker-result" class="cmp-cost-output" role="status" aria-live="polite"></div><p>Formel: Jahreskosten = Orders × (Fixpreis + Volumen × Provision ÷ 100) + 12 × Monatsgebühr. Ohne Spreads, Fremdkosten, Währungswechsel, Steuern oder Produktkosten. Fehlende Gebühren selbst ergänzen, sonst kein Gesamtkostenvergleich.</p></section><h2>Zehn Broker: Bedingungen statt Kurznoten</h2><div class="cmp-brokers">'+rows+'</div>'+scripts
    publish('depot','Depot & Broker: Was kostet dein Handelsstil?','Zehn Anbieter alphabetisch aus einem offen lizenzierten Datensatz. Ohne Affiliate, Testsieger-Siegel oder pauschale Bestenliste.',broker)
    stats=load_series(refresh=False);blocks=''
    for s in stats:
        latest=s['rows'][-1];blocks+='<article class="cmp-stat"><p class="calc-kicker">DEUTSCHLAND / MONATLICH</p><h2>'+e(s['label'])+'</h2><p class="cmp-rate">'+n(latest['OBS_VALUE'])+' % <small>p. a.</small></p><p>Berichtsmonat '+latest['TIME_PERIOD']+' · Status '+e(latest['OBS_STATUS'])+' (P = vorläufig, A = normal)</p>'+spark(s['rows'])+'<p class="cmp-range">'+s['rows'][0]['TIME_PERIOD']+' bis '+latest['TIME_PERIOD']+' · eigene Skala je Diagramm</p><details><summary>Werte und Original-Metadaten</summary><div class="calc-table"><table><caption>Unveränderte Beobachtungswerte der EZB</caption><tr><th>Monat</th><th>% p. a.</th><th>Status</th></tr>'+''.join('<tr><th>'+r['TIME_PERIOD']+'</th><td>'+e(r['OBS_VALUE'])+'</td><td>'+e(r['OBS_STATUS'])+'</td></tr>' for r in s['rows'])+'</table></div><p>'+e(latest.get('TITLE_COMPL',''))+'</p><p>Einheit: '+e(latest['UNIT'])+' · Multiplikator: '+e(latest['UNIT_MULT'])+' · Serie MIR.'+e(s['key'])+'</p></details><a href="'+e(s['download'],quote=True)+'">Original-CSV abrufen ↗</a> · <a href="/comparison-data/'+s['key']+'.csv">FA-Snapshot (CSV)</a></article>'
    publish('zinsmonitor','Der amtliche Zinsmonitor','EZB-Zinsstatistik für Deutschland. Beobachtete Monatswerte statt tagesaktueller Lockangebote. Keine Einzelbanken, keine Produktempfehlungen.','<p class="cmp-alert">Quelle: EZB-Statistiken. Snapshot abgerufen am 19.10.2026. Neuester verfügbarer Berichtsmonat im Snapshot: August 2026. Das ist kein heutiger Tagesgeld- oder Kreditzins. Berichtsverzug und Revisionen sind normal.</p><div class="cmp-stat-grid">'+blocks+'</div><section class="calc-info"><h2>Was ist hier vergleichbar?</h2><p>Täglich fällige Einlagen sind eine breite statistische Kategorie einschließlich anderer täglich verfügbarer Konten, kein Durchschnitt nur der beworbenen Tagesgeldangebote. Einlagen bis ein Jahr betreffen vereinbarte Laufzeiten im Neugeschäft. Beide sind annualisierte vereinbarte Zinssätze (AAR/NDER). Konsumkredite zeigen dagegen effektive Jahreszinsen (APRC), nicht nominale Sollzinsen. Daher werden sie nicht ungeprüft in unseren Sollzins-Kreditrechner übernommen.</p><p>Die Grundgesamtheit umfasst private Haushalte und private Organisationen ohne Erwerbszweck, Euro-Geschäfte deutscher berichtender Institute. Werte und Original-Metadaten bleiben im CSV unverändert; deutsche Kurzbezeichnungen und SVGs sind FA-Darstellungen. Keine Partnerschaft oder Unterstützung durch die EZB.</p><p><a href="'+POLICY+'">Freie Weiterverwendung von ESZB-Statistiken</a> · <a href="https://data.ecb.europa.eu/help/api/data">Dokumentation der EZB-Schnittstelle</a></p><p>Aktualisierung des Snapshots erfolgt durch einen expliziten Datenlauf, nicht bei jedem Besuch. Der Stand wird nicht durch ein neues Seitendatum kaschiert. <a href="/rechner/kredit/">Eigenes Kreditmodell</a> · <a href="/rechner/zinseszins/">Eigene Zinsannahmen rechnen</a></p></section>')
    # Add a discoverable bridge without modifying the calculator renderer.
    hub=Path(out)/'rechner/index.html'
    if hub.exists():hub.write_text(hub.read_text().replace('<section aria-label="Alle Finanzrechner">','<aside class="calc-note"><h2>Von der Rechnung zum Konditionenvergleich</h2><p><a href="/vergleiche/">Tagesgeld, Depot/Broker und amtlichen Zinsmonitor ansehen →</a> · Offene Daten, sichtbarer Stand, keine Affiliate-Links.</p></aside><section aria-label="Alle Finanzrechner">'))
